/**
 * The updater's vocabulary.
 *
 * Nothing in this module talks to Tauri, the network, or React. The state
 * machine and the service are the only consumers, which keeps the whole
 * lifecycle testable in a plain jsdom process.
 */

export type UpdatePhase =
  /** Not running inside the desktop shell (browser tab or `tauri dev`). */
  | "unsupported"
  /** Supported, but no check has finished yet. */
  | "idle"
  | "checking"
  | "downloading"
  | "installing"
  /** Downloaded; `installed` says whether a relaunch is all that remains. */
  | "ready"
  | "up-to-date"
  | "error";

export interface AvailableUpdate {
  version: string;
  /** RFC 3339 date from the update manifest, when published. */
  date: string | null;
  /** Release notes from the update manifest, when published. */
  notes: string | null;
}

export interface DownloadProgress {
  received: number;
  total: number | null;
}

export interface UpdateSnapshot {
  phase: UpdatePhase;
  currentVersion: string | null;
  available: AvailableUpdate | null;
  progress: DownloadProgress | null;
  lastCheckedAt: number | null;
  /** True when the artifact is staged and the next launch runs it. */
  installed: boolean;
  /** True when the artifact is downloaded but needs an app exit to install. */
  pendingInstall: boolean;
  error: string | null;
  autoCheck: boolean;
  /** Persisted: the person asked not to be offered this version again. */
  skippedVersion: string | null;
  /** Session-only: the person hid the banner. */
  dismissedVersion: string | null;
}

export type UpdateEvent =
  | { type: "unsupported" }
  | { type: "current-version"; version: string }
  | { type: "check-started" }
  | { type: "check-none"; currentVersion: string | null; at: number }
  | {
      type: "check-skipped";
      currentVersion: string;
      update: AvailableUpdate;
      at: number;
    }
  | {
      type: "check-found";
      currentVersion: string;
      update: AvailableUpdate;
      at: number;
    }
  | { type: "download-progress"; received: number; total: number | null }
  | { type: "download-finished" }
  | { type: "download-finished-pending" }
  | { type: "install-started" }
  | { type: "installed" }
  | { type: "failed"; message: string; at: number }
  | { type: "relaunch-failed"; message: string }
  | { type: "dismissed" }
  | { type: "skipped"; version: string }
  | { type: "auto-check-changed"; enabled: boolean }
  | { type: "reset"; currentVersion?: string | null };

/** The Update resource exposed by `@tauri-apps/plugin-updater`, narrowed down. */
export interface UpdaterHandle {
  version: string;
  currentVersion: string;
  date: string | null;
  notes: string | null;
  download(onProgress: (progress: DownloadProgress) => void): Promise<void>;
  install(): Promise<void>;
  close(): Promise<void>;
}

/**
 * The seam between the updater lifecycle and the desktop runtime. The service
 * only ever sees this interface; tests supply a fake.
 */
export interface UpdateTransport {
  supported(): boolean;
  currentVersion(): Promise<string>;
  check(): Promise<UpdaterHandle | null>;
  relaunch(): Promise<void>;
}

export interface UpdatePreferences {
  autoCheck: boolean;
  skippedVersion: string | null;
}

/**
 * The updater's state machine — a pure reducer plus selectors.
 *
 * Every surface (banner, sidebar, Settings) reads the same snapshot, so they
 * can never disagree about whether an update is available, downloading, or
 * waiting for a restart.
 */
import type { UpdateEvent, UpdateSnapshot } from "./types";

export const INITIAL_SNAPSHOT: UpdateSnapshot = {
  phase: "idle",
  currentVersion: null,
  available: null,
  progress: null,
  lastCheckedAt: null,
  installed: false,
  pendingInstall: false,
  error: null,
  autoCheck: true,
  skippedVersion: null,
  dismissedVersion: null,
};

export function initialSnapshot(
  overrides: Partial<UpdateSnapshot> = {},
): UpdateSnapshot {
  return { ...INITIAL_SNAPSHOT, ...overrides };
}

/** Apply one event. Unknown phases fall back to the untouched snapshot. */
export function reduce(snapshot: UpdateSnapshot, event: UpdateEvent): UpdateSnapshot {
  switch (event.type) {
    case "unsupported":
      return { ...snapshot, phase: "unsupported", error: null };

    case "current-version":
      return event.version === snapshot.currentVersion
        ? snapshot
        : { ...snapshot, currentVersion: event.version };

    case "check-started":
      return { ...snapshot, phase: "checking", error: null };

    case "check-none":
      return {
        ...snapshot,
        phase: "up-to-date",
        currentVersion: event.currentVersion,
        available: null,
        progress: null,
        installed: false,
        pendingInstall: false,
        lastCheckedAt: event.at,
        error: null,
        dismissedVersion: null,
      };

    case "check-skipped":
      return {
        ...snapshot,
        phase: "up-to-date",
        currentVersion: event.currentVersion,
        available: event.update,
        progress: null,
        installed: false,
        pendingInstall: false,
        lastCheckedAt: event.at,
        error: null,
      };

    case "check-found":
      return {
        ...snapshot,
        phase: "downloading",
        currentVersion: event.currentVersion,
        available: event.update,
        progress: { received: 0, total: null },
        installed: false,
        pendingInstall: false,
        lastCheckedAt: event.at,
        error: null,
        dismissedVersion: null,
      };

    case "download-progress":
      if (snapshot.phase !== "downloading" && snapshot.phase !== "installing") {
        return snapshot;
      }
      return {
        ...snapshot,
        phase: "downloading",
        progress: { received: event.received, total: event.total },
      };

    case "download-finished":
      return {
        ...snapshot,
        phase: "installing",
        progress: snapshot.progress,
        error: null,
      };

    case "download-finished-pending":
      return {
        ...snapshot,
        phase: "ready",
        progress: null,
        installed: false,
        pendingInstall: true,
        error: null,
      };

    case "install-started":
      return { ...snapshot, phase: "installing", error: null };

    case "installed":
      return {
        ...snapshot,
        phase: "ready",
        progress: null,
        installed: true,
        pendingInstall: false,
        error: null,
      };

    case "failed":
      return {
        ...snapshot,
        phase: "error",
        progress: null,
        installed: false,
        pendingInstall: false,
        lastCheckedAt: event.at,
        error: event.message,
      };

    case "relaunch-failed":
      // The update is already staged; only the relaunch failed. Keep
      // `installed` so the next retry does not reinstall what is on disk.
      return { ...snapshot, phase: "error", error: event.message, progress: null };

    case "dismissed":
      return {
        ...snapshot,
        dismissedVersion: snapshot.available?.version ?? null,
      };

    case "skipped":
      return {
        ...snapshot,
        phase: "up-to-date",
        skippedVersion: event.version,
        dismissedVersion: event.version,
        progress: null,
        installed: false,
        pendingInstall: false,
      };

    case "auto-check-changed":
      return { ...snapshot, autoCheck: event.enabled };

    case "reset":
      return {
        ...snapshot,
        phase: "idle",
        currentVersion: event.currentVersion ?? snapshot.currentVersion,
        available: null,
        progress: null,
        installed: false,
        pendingInstall: false,
        error: null,
        dismissedVersion: null,
      };

    default:
      return snapshot;
  }
}

/** 0…1, or null while the server has not told us the size yet. */
export function progressPercent(snapshot: UpdateSnapshot): number | null {
  const progress = snapshot.progress;
  if (!progress || progress.total === null || progress.total <= 0) {
    return null;
  }
  return Math.max(0, Math.min(1, progress.received / progress.total));
}

export type BannerKind = "downloading" | "ready" | "installing" | "error";

export interface BannerView {
  kind: BannerKind;
  version: string;
  percent: number | null;
  pendingInstall: boolean;
}

/**
 * What the shell should show, if anything.
 *
 * Deliberately silent for background-check failures (nothing to act on), for
 * versions the person skipped or dismissed, and for an up-to-date app. The
 * Settings section is where failures remain visible.
 */
export function bannerView(snapshot: UpdateSnapshot): BannerView | null {
  const update = snapshot.available;
  if (!update || snapshot.phase === "unsupported") {
    return null;
  }
  if (
    update.version === snapshot.skippedVersion ||
    update.version === snapshot.dismissedVersion
  ) {
    return null;
  }

  const view = {
    version: update.version,
    percent: progressPercent(snapshot),
    pendingInstall: snapshot.pendingInstall,
  };

  switch (snapshot.phase) {
    case "downloading":
    case "installing":
    case "ready":
    case "error":
      return { ...view, kind: snapshot.phase === "installing" ? "installing" : snapshot.phase };
    default:
      return null;
  }
}

/** True when the primary action should restart (rather than install first). */
export function canRestartNow(snapshot: UpdateSnapshot): boolean {
  return snapshot.phase === "ready" && snapshot.installed;
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export function describeCheckedAt(at: number | null, now: number): string {
  if (at === null) {
    return "Not checked yet";
  }
  const elapsed = Math.max(0, now - at);
  if (elapsed < MINUTE) {
    return "Checked just now";
  }
  if (elapsed < HOUR) {
    const minutes = Math.round(elapsed / MINUTE);
    return `Checked ${minutes} minute${minutes === 1 ? "" : "s"} ago`;
  }
  if (elapsed < DAY) {
    const hours = Math.round(elapsed / HOUR);
    return `Checked ${hours} hour${hours === 1 ? "" : "s"} ago`;
  }
  const days = Math.round(elapsed / DAY);
  return `Checked ${days} day${days === 1 ? "" : "s"} ago`;
}

/** One plain sentence for Settings. Never an error code. */
export function statusLine(snapshot: UpdateSnapshot, now: number): string {
  const version = snapshot.available?.version ?? null;

  if (snapshot.phase === "unsupported") {
    return "In-app updates live in the installed desktop app.";
  }

  if (snapshot.phase === "error") {
    return snapshot.error ?? "The update could not be completed.";
  }

  if (snapshot.phase === "checking") {
    return "Checking for updates…";
  }

  if (snapshot.phase === "downloading") {
    const percent = progressPercent(snapshot);
    return percent === null
      ? `Downloading Living Studio ${version ?? ""}…`
      : `Downloading Living Studio ${version ?? ""} — ${Math.round(percent * 100)}%`;
  }

  if (snapshot.phase === "installing") {
    return `Installing Living Studio ${version ?? ""}…`;
  }

  if (snapshot.phase === "ready") {
    if (snapshot.pendingInstall) {
      return `Living Studio ${version ?? ""} is downloaded. Updating restarts the app.`;
    }
    return `Living Studio ${version ?? ""} is ready. Restart to finish.`;
  }

  if (version && version === snapshot.skippedVersion) {
    return `Living Studio ${version} is skipped. You will be offered the next release.`;
  }

  if (snapshot.phase === "up-to-date") {
    return "You're up to date.";
  }

  return describeCheckedAt(snapshot.lastCheckedAt, now);
}

/**
 * The update lifecycle: when to check, what to download, when to install, and
 * when to hand control back to the person.
 *
 * It has no idea what Tauri is. A transport supplies the runtime, timers come
 * from the environment, and preferences come from injected storage — which is
 * what makes the whole thing testable without a desktop build.
 */
import {
  initialSnapshot,
  reduce,
  progressPercent,
  type BannerView,
  bannerView,
  canRestartNow,
  describeCheckedAt,
  statusLine,
} from "./machine";
import { detectPlatform, installAfterDownload, type DesktopPlatform } from "./platform";
import type {
  UpdateEvent,
  UpdatePreferences,
  UpdateSnapshot,
  UpdateTransport,
  UpdaterHandle,
} from "./types";

export const AUTO_CHECK_KEY = "studio.update.autoCheck";
export const SKIPPED_VERSION_KEY = "studio.update.skippedVersion";

const DEFAULT_INITIAL_DELAY_MS = 4_000;
const DEFAULT_INTERVAL_MS = 6 * 60 * 60 * 1_000;

type PreferenceStorage = Pick<Storage, "getItem" | "setItem" | "removeItem">;

export interface UpdateServiceOptions {
  transport: UpdateTransport;
  storage?: PreferenceStorage | null;
  platform?: DesktopPlatform;
  now?: () => number;
  initialDelayMs?: number;
  intervalMs?: number;
  document?: Pick<Document, "addEventListener" | "removeEventListener" | "visibilityState"> | null;
}

export interface UpdateService {
  getSnapshot(): UpdateSnapshot;
  subscribe(listener: () => void): () => void;
  start(): void;
  stop(): void;
  dispose(): void;
  check(): Promise<void>;
  /** Retry after a failure: installs staged bytes, otherwise checks again. */
  retry(): Promise<void>;
  installAndRestart(): Promise<void>;
  dismiss(): void;
  skipCurrent(): void;
  setAutoCheck(enabled: boolean): void;
  bannerView(): BannerView | null;
  statusLine(): string;
  checkedAtLabel(): string;
  canRestartNow(): boolean;
  progressPercent(): number | null;
}

function readStorage(storage: PreferenceStorage | null): UpdatePreferences {
  if (!storage) {
    return { autoCheck: true, skippedVersion: null };
  }
  try {
    return {
      autoCheck: storage.getItem(AUTO_CHECK_KEY) !== "off",
      skippedVersion: storage.getItem(SKIPPED_VERSION_KEY),
    };
  } catch {
    return { autoCheck: true, skippedVersion: null };
  }
}

function defaultStorage(): PreferenceStorage | null {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

/** Plain language, never a stack trace. */
export function describeUpdateFailure(
  error: unknown,
  stage: "check" | "download" | "install",
): string {
  const raw = error instanceof Error ? error.message : String(error ?? "");

  if (/signature/i.test(raw)) {
    return "The update couldn't be verified. Try again, or install the latest release.";
  }
  if (/permission|denied|not permitted|read-only|readonly|privilege/i.test(raw)) {
    return "The app couldn't replace itself. Install the latest release instead.";
  }
  if (stage === "check") {
    return "Couldn't reach the update server.";
  }
  if (stage === "download") {
    return "The download didn't finish. Check your connection and try again.";
  }
  return "The update couldn't be installed. Try again.";
}

export function createUpdateService(options: UpdateServiceOptions): UpdateService {
  const { transport } = options;
  const platform = options.platform ?? detectPlatform();
  const now = options.now ?? (() => Date.now());
  const storage = options.storage === undefined ? defaultStorage() : options.storage;
  const documentRef =
    options.document === undefined
      ? typeof document === "undefined"
        ? null
        : document
      : options.document;
  const initialDelayMs = options.initialDelayMs ?? DEFAULT_INITIAL_DELAY_MS;
  const intervalMs = options.intervalMs ?? DEFAULT_INTERVAL_MS;

  const preferences = readStorage(storage);
  let snapshot: UpdateSnapshot = initialSnapshot({
    autoCheck: preferences.autoCheck,
    skippedVersion: preferences.skippedVersion,
  });

  const listeners = new Set<() => void>();
  let handle: UpdaterHandle | null = null;
  let downloaded = false;
  let inFlight: Promise<void> | null = null;
  let started = false;
  let firstCheck: ReturnType<typeof setTimeout> | null = null;
  let poller: ReturnType<typeof setInterval> | null = null;

  function emit(event: UpdateEvent): void {
    const next = reduce(snapshot, event);
    if (next === snapshot) {
      return;
    }
    snapshot = next;
    for (const listener of listeners) {
      listener();
    }
  }

  function forgetHandle(): void {
    const previous = handle;
    handle = null;
    downloaded = false;
    if (previous) {
      void previous.close().catch(() => undefined);
    }
  }

  function persistSkipped(version: string | null): void {
    if (!storage) {
      return;
    }
    try {
      if (version) {
        storage.setItem(SKIPPED_VERSION_KEY, version);
      } else {
        storage.removeItem(SKIPPED_VERSION_KEY);
      }
    } catch {
      /* preferences are a convenience, never a blocker */
    }
  }

  async function syncCurrentVersion(): Promise<void> {
    try {
      const version = await transport.currentVersion();
      if (version) {
        emit({ type: "current-version", version });
      }
    } catch {
      /* the version is cosmetic until a check succeeds */
    }
  }

  async function runCheck(): Promise<void> {
    if (inFlight) {
      return inFlight;
    }
    if (!transport.supported()) {
      emit({ type: "unsupported" });
      return;
    }
    if (snapshot.phase === "ready" || snapshot.phase === "installing") {
      return;
    }

    emit({ type: "check-started" });

    inFlight = (async () => {
      let stage: "check" | "download" | "install" = "check";
      try {
        const update = await transport.check();
        if (!update) {
          forgetHandle();
          emit({
            type: "check-none",
            currentVersion: snapshot.currentVersion,
            at: now(),
          });
          return;
        }

        const current = update.currentVersion || snapshot.currentVersion || "";
        if (snapshot.currentVersion !== current) {
          emit({ type: "current-version", version: current });
        }

        const info = {
          version: update.version,
          date: update.date,
          notes: update.notes,
        };

        if (snapshot.skippedVersion === update.version) {
          forgetHandle();
          emit({
            type: "check-skipped",
            currentVersion: current,
            update: info,
            at: now(),
          });
          return;
        }

        forgetHandle();
        handle = update;

        emit({
          type: "check-found",
          currentVersion: current,
          update: info,
          at: now(),
        });

        stage = "download";
        await update.download((progress) => {
          emit({
            type: "download-progress",
            received: progress.received,
            total: progress.total,
          });
        });
        downloaded = true;

        emit({ type: "download-finished" });

        if (!installAfterDownload(platform)) {
          emit({ type: "download-finished-pending" });
          return;
        }

        stage = "install";
        emit({ type: "install-started" });
        await update.install();
        emit({ type: "installed" });
      } catch (error) {
        emit({
          type: "failed",
          message: describeUpdateFailure(error, stage),
          at: now(),
        });
      }
    })().finally(() => {
      inFlight = null;
    });

    return inFlight;
  }

  async function installThenRelaunch(): Promise<void> {
    if (handle && !snapshot.installed && snapshot.pendingInstall) {
      try {
        emit({ type: "install-started" });
        await handle.install();
        emit({ type: "installed" });
      } catch (error) {
        emit({
          type: "failed",
          message: describeUpdateFailure(error, "install"),
          at: now(),
        });
        return;
      }
    }

    try {
      await transport.relaunch();
    } catch {
      emit({
        type: "relaunch-failed",
        message: "The app couldn't restart. Close and reopen it to finish updating.",
      });
    }
  }

  function stopTimers(): void {
    started = false;
    if (firstCheck !== null) {
      clearTimeout(firstCheck);
      firstCheck = null;
    }
    if (poller !== null) {
      clearInterval(poller);
      poller = null;
    }
    documentRef?.removeEventListener("visibilitychange", onVisibilityChange);
  }

  function onVisibilityChange(): void {
    if (!snapshot.autoCheck || documentRef?.visibilityState !== "visible") {
      return;
    }
    const last = snapshot.lastCheckedAt;
    if (last === null || now() - last >= intervalMs) {
      void runCheck();
    }
  }

  return {
    getSnapshot: () => snapshot,

    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },

    start() {
      if (started) {
        return;
      }
      started = true;

      if (!transport.supported()) {
        emit({ type: "unsupported" });
        return;
      }

      void syncCurrentVersion();

      if (snapshot.autoCheck) {
        firstCheck = setTimeout(() => {
          if (snapshot.autoCheck) {
            void runCheck();
          }
        }, initialDelayMs);
      }

      poller = setInterval(() => {
        if (snapshot.autoCheck) {
          void runCheck();
        }
      }, intervalMs);

      documentRef?.addEventListener("visibilitychange", onVisibilityChange);
    },

    stop() {
      stopTimers();
    },

    dispose() {
      stopTimers();
      listeners.clear();
      forgetHandle();
    },

    check() {
      return runCheck();
    },

    async retry() {
      if (snapshot.installed) {
        await installThenRelaunch();
        return;
      }
      if (downloaded && handle && snapshot.error) {
        try {
          emit({ type: "install-started" });
          await handle.install();
          emit({ type: "installed" });
          return;
        } catch (error) {
          emit({
            type: "failed",
            message: describeUpdateFailure(error, "install"),
            at: now(),
          });
          return;
        }
      }
      await runCheck();
    },

    installAndRestart() {
      return installThenRelaunch();
    },

    dismiss() {
      emit({ type: "dismissed" });
    },

    skipCurrent() {
      const version = snapshot.available?.version;
      if (!version) {
        return;
      }
      persistSkipped(version);
      forgetHandle();
      emit({ type: "skipped", version });
    },

    setAutoCheck(enabled: boolean) {
      if (storage) {
        try {
          storage.setItem(AUTO_CHECK_KEY, enabled ? "on" : "off");
        } catch {
          /* preferences are a convenience, never a blocker */
        }
      }
      emit({ type: "auto-check-changed", enabled });
      if (enabled) {
        const last = snapshot.lastCheckedAt;
        if (last === null || now() - last >= intervalMs) {
          void runCheck();
        }
      }
    },

    bannerView: () => bannerView(snapshot),
    statusLine: () => statusLine(snapshot, now()),
    checkedAtLabel: () => describeCheckedAt(snapshot.lastCheckedAt, now()),
    canRestartNow: () => canRestartNow(snapshot),
    progressPercent: () => progressPercent(snapshot),
  };
}

/**
 * The only module in the updater that knows Tauri exists.
 *
 * Everything above it — state machine, service, components — works against the
 * `UpdateTransport` interface, which is what lets the entire lifecycle run in
 * a plain test process.
 */
import { getVersion } from "@tauri-apps/api/app";
import { relaunch } from "@tauri-apps/plugin-process";
import { check, type DownloadEvent } from "@tauri-apps/plugin-updater";

import { isTauri } from "../bridge/desktopBridge";
import type { DownloadProgress, UpdateTransport, UpdaterHandle } from "./types";

function handleFor(update: NonNullable<Awaited<ReturnType<typeof check>>>): UpdaterHandle {
  return {
    version: update.version,
    currentVersion: update.currentVersion,
    date: update.date ?? null,
    notes: update.body ?? null,

    async download(onProgress: (progress: DownloadProgress) => void) {
      let received = 0;
      let total: number | null = null;

      await update.download((event: DownloadEvent) => {
        if (event.event === "Started") {
          total = event.data.contentLength ?? null;
          onProgress({ received, total });
          return;
        }
        if (event.event === "Progress") {
          received += event.data.chunkLength;
          onProgress({ received, total });
        }
      });
    },

    install: () => update.install(),
    close: () => update.close(),
  };
}

export function createDesktopTransport(): UpdateTransport {
  return {
    supported: () => isTauri(),

    async currentVersion() {
      return getVersion();
    },

    async check() {
      const update = await check();
      return update ? handleFor(update) : null;
    },

    async relaunch() {
      await relaunch();
    },
  };
}

/**
 * The one behaviour that differs per desktop OS.
 *
 * macOS and Linux can replace their own bundle while the app is running, so an
 * update is staged as soon as it downloads and the next ordinary launch runs it.
 * Windows runs an NSIS installer that needs the app to exit first, so installing
 * is bound to the explicit "Update & restart" action.
 */
export type DesktopPlatform = "macos" | "windows" | "linux" | "unknown";

export function detectPlatform(userAgent?: string): DesktopPlatform {
  const ua = (
    userAgent ??
    (typeof navigator === "undefined" ? "" : navigator.userAgent)
  ).toLowerCase();

  if (ua.includes("windows")) {
    return "windows";
  }
  if (ua.includes("mac os") || ua.includes("macintosh")) {
    return "macos";
  }
  if (ua.includes("linux") || ua.includes("x11")) {
    return "linux";
  }
  return "unknown";
}

export function installAfterDownload(platform: DesktopPlatform): boolean {
  return platform !== "windows";
}

/* eslint-disable react-refresh/only-export-components -- the provider and its hooks intentionally share one module */
import {
  createContext,
  useContext,
  useEffect,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";

import { createUpdateService, type UpdateService } from "./service";
import { createDesktopTransport } from "./transport";
import type { UpdateSnapshot } from "./types";

const UpdateContext = createContext<UpdateService | null>(null);

function createDefaultService(): UpdateService {
  const transport = createDesktopTransport();
  return createUpdateService({
    transport: {
      ...transport,
      // `tauri dev` serves the Vite dev build; there is no installed bundle for
      // the updater to replace, so say so instead of reporting a failed check.
      supported: () => transport.supported() && !import.meta.env.DEV,
    },
  });
}

interface UpdateProviderProps {
  children: ReactNode;
  /** Injected by tests; the app creates one desktop-backed service. */
  service?: UpdateService;
}

export function UpdateProvider({ children, service }: UpdateProviderProps) {
  const [instance] = useState(() => service ?? createDefaultService());

  useEffect(() => {
    instance.start();
    return () => instance.stop();
  }, [instance]);

  return <UpdateContext.Provider value={instance}>{children}</UpdateContext.Provider>;
}

export function useUpdateService(): UpdateService {
  const service = useContext(UpdateContext);
  if (!service) {
    throw new Error("useUpdateService must be used within an UpdateProvider");
  }
  return service;
}

/** The single source of truth for every update surface in the shell. */
export function useUpdateSnapshot(): UpdateSnapshot {
  const service = useUpdateService();
  return useSyncExternalStore(service.subscribe, service.getSnapshot, service.getSnapshot);
}

import { CheckIcon } from "../components/icons";
import { useUpdateService, useUpdateSnapshot } from "./UpdateProvider";
import { bannerView } from "./machine";

/**
 * One quiet line about the update, above the conversation.
 *
 * It never blocks, never takes focus, and never says anything a person cannot
 * act on. Dismissing it is always safe: a staged update still applies on the
 * next launch.
 */
export function UpdateBanner() {
  const service = useUpdateService();
  const snapshot = useUpdateSnapshot();
  const view = bannerView(snapshot);

  if (!view) {
    return null;
  }

  const percent = view.percent;
  const percentLabel = percent === null ? null : `${Math.round(percent * 100)}%`;

  const { title, detail } = (() => {
    switch (view.kind) {
      case "downloading":
        return {
          title: `Getting Living Studio ${view.version} ready`,
          detail: "Downloading in the background — you can keep working.",
        };
      case "installing":
        return {
          title: `Installing Living Studio ${view.version}`,
          detail: "One moment.",
        };
      case "ready":
        return {
          title: `Living Studio ${view.version} is ready`,
          detail: view.pendingInstall
            ? "Updating closes and reopens the app."
            : "Restart now, or it will apply the next time you open the studio.",
        };
      default:
        return {
          title: "The update didn't finish",
          detail: snapshot.error ?? "Try again in a moment.",
        };
    }
  })();

  const primary =
    view.kind === "ready" ? (
      <button
        type="button"
        className="button update-banner__action"
        onClick={() => void service.installAndRestart()}
      >
        {view.pendingInstall ? "Update & restart" : "Restart now"}
      </button>
    ) : view.kind === "error" ? (
      <button
        type="button"
        className="button update-banner__action"
        onClick={() => void service.retry()}
      >
        Try again
      </button>
    ) : null;

  return (
    <section
      className={`update-banner update-banner--${view.kind}`}
      role="status"
      aria-live="polite"
      aria-label="Software update"
    >
      <span className="update-banner__mark" aria-hidden="true">
        {view.kind === "ready" ? <CheckIcon size={15} /> : "◍"}
      </span>

      <div className="update-banner__copy">
        <p className="update-banner__title">{title}</p>
        <p className="update-banner__detail">{detail}</p>
      </div>

      {view.kind === "downloading" && (
        <span
          className="update-banner__progress"
          role="progressbar"
          aria-label="Update download progress"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={percent === null ? undefined : Math.round(percent * 100)}
        >
          <span
            className="update-banner__progress-fill"
            style={{ width: percent === null ? "12%" : `${Math.max(2, percent * 100)}%` }}
          />
        </span>
      )}

      {percentLabel && <span className="update-banner__percent">{percentLabel}</span>}

      <div className="update-banner__actions">
        {primary}
        {view.kind !== "installing" && (
          <button
            type="button"
            className="update-banner__dismiss"
            aria-label="Dismiss update notice"
            title="Not now"
            onClick={() => service.dismiss()}
          >
            ×
          </button>
        )}
      </div>
    </section>
  );
}

import { useUpdateService, useUpdateSnapshot } from "./UpdateProvider";

/**
 * The honest, complete picture: the running version, what the updater is doing,
 * the release notes, and the two preferences that matter.
 */
export function UpdateSettings() {
  const service = useUpdateService();
  const snapshot = useUpdateSnapshot();

  const supported = snapshot.phase !== "unsupported";
  const busy =
    snapshot.phase === "checking" ||
    snapshot.phase === "downloading" ||
    snapshot.phase === "installing";
  const version = snapshot.currentVersion;
  const notes = snapshot.available?.notes;
  const canSkip =
    snapshot.available !== null &&
    !snapshot.installed &&
    (snapshot.phase === "error" || snapshot.phase === "ready");
  const dotClass =
    snapshot.phase === "error"
      ? " is-warn"
      : snapshot.phase === "ready"
        ? " is-ready"
        : busy
          ? " is-busy"
          : "";

  return (
    <section className="update-settings" aria-labelledby="software-update-heading">
      <div className="update-settings__head">
        <h3 className="settings__title" id="software-update-heading">
          Software update
        </h3>
        {version && <span className="update-settings__version">v{version}</span>}
      </div>

      <p className="update-settings__status">
        <span className={`status-dot${dotClass}`} aria-hidden="true" />
        <span>{service.statusLine()}</span>
      </p>

      {supported && snapshot.lastCheckedAt !== null && (
        <p className="muted">{service.checkedAtLabel()}</p>
      )}

      {snapshot.available && notes && (
        <details className="disclosure update-settings__notes">
          <summary>What's new in {snapshot.available.version}</summary>
          <p className="update-settings__notes-body">{notes}</p>
        </details>
      )}

      {supported && (
        <div className="update-settings__actions">
          {snapshot.phase === "ready" ? (
            <button
              type="button"
              className="button"
              onClick={() => void service.installAndRestart()}
            >
              {snapshot.pendingInstall ? "Update & restart" : "Restart now"}
            </button>
          ) : snapshot.phase === "error" ? (
            <button type="button" className="button" onClick={() => void service.retry()}>
              Try again
            </button>
          ) : (
            <button
              type="button"
              className="button button--ghost"
              disabled={busy}
              onClick={() => void service.check()}
            >
              {snapshot.phase === "checking" ? "Checking…" : "Check now"}
            </button>
          )}

          {canSkip && snapshot.available && (
            <button
              type="button"
              className="button button--ghost"
              onClick={() => service.skipCurrent()}
            >
              Skip this version
            </button>
          )}
        </div>
      )}

      {supported && (
        <label className="update-settings__toggle">
          <input
            type="checkbox"
            checked={snapshot.autoCheck}
            onChange={(event) => service.setAutoCheck(event.target.checked)}
          />
          <span>Check for updates automatically</span>
        </label>
      )}
    </section>
  );
}

